    const target = b.standardTargetOptions(.{});
    const optimize = b.standardOptimizeOption(.{});

    const exe = b.addExecutable(.{
        .name = "formal_verification",
        .root_source_file = .{ .path = "src/formal_verification.zig" },
        .target = target,
        .optimize = optimize,
    });

