    exe.linkSystemLibrary("napi");
    exe.linkSystemLibrary("node");

    exe.addIncludePath(.{ .path = "node_modules/snarkjs" });
    exe.addIncludePath(.{ .path = "circom" });

    const run_cmd = b.addRunArtifact(exe);
    run_cmd.step.dependOn(&exe.step);

