    pi_c: [2][32]u8,
    protocol: [8]u8,
    curve: [8]u8,
};

pub const CircomVerifier = struct {
    allocator: std.mem.Allocator,
    circuit_path: []const u8,
    proving_key: []const u8,
    verification_key: []const u8,
    c_bridge: ?*c.SnarkjsBridge = null,

    pub fn init(allocator: std.mem.Allocator, circuit: []const u8, pkey: []const u8, vkey: []const u8) !CircomVerifier {
        return .{
            .allocator = allocator,
            .circuit_path = try allocator.dupe(u8, circuit),
            .proving_key = try allocator.dupe(u8, pkey),
            .verification_key = try allocator.dupe(u8, vkey),
        };
    }

    pub fn deinit(self: *CircomVerifier) void {
        self.allocator.free(self.circuit_path);
        self.allocator.free(self.proving_key);
        self.allocator.free(self.verification_key);
        if (self.c_bridge) |bridge| {
            c.snarkjs_bridge_destroy(bridge);
        }
    }

    pub fn initBridge(self: *CircomVerifier) !void {
        self.c_bridge = c.snarkjs_bridge_init(
            self.circuit_path.ptr,
            self.proving_key.ptr,
            self.verification_key.ptr,
        ) orelse return error.BridgeInitFailed;
    }

    pub fn generateWitness(self: *CircomVerifier, inputs: []const u8) ![]u8 {
        if (self.c_bridge) |bridge| {
            const witness_ptr = c.snarkjs_compute_witness(bridge, inputs.ptr, inputs.len);
            if (witness_ptr == null) return error.WitnessFailed;
            return try self.parseWitness(witness_ptr);
        }
        return try self.generateWitnessNode(inputs);
    }

    pub fn generateProof(self: *CircomVerifier, witness: []const u8) !CircomProof {
        if (self.c_bridge) |bridge| {
            const proof_ptr = c.snarkjs_generate_proof(bridge, witness.ptr, witness.len);
            if (proof_ptr == null) return error.ProofFailed;
            var proof: CircomProof = undefined;
            @memcpy(&proof, proof_ptr);
            return proof;
        }
        return try self.generateProofNode(witness);
    }

    pub fn verifyProof(self: *CircomVerifier, proof: CircomProof, public_inputs: []const []const u8) bool {
        if (self.c_bridge) |bridge| {
            return c.snarkjs_verify_proof(bridge, &proof, public_inputs.ptr, public_inputs.len) == 1;
        }
        return self.verifyProofNode(proof, public_inputs);
    }

    fn generateWitnessNode(self: *CircomVerifier, inputs: []const u8) ![]u8 {
        const argv = [_][]const u8{ "node", "node_modules/snarkjs/cli.js", "wtns", "calculate", self.circuit_path, "/tmp/input.json", "/tmp/witness.wtns" };
        const child = std.ChildProcess.init(&argv, self.allocator);
        child.stdin_behavior = .Pipe;
        child.stdout_behavior = .Pipe;
        child.stderr_behavior = .Pipe;

        try child.spawn();
        _ = try child.stdin.?.writeAll(inputs);
        child.stdin.?.close();

        const term = try child.wait();
        if (term != .Exited or child.kill() != .Success) {
            return error.SubprocessFailed;
        }

        return try std.fs.cwd().readFileAlloc(self.allocator, "/tmp/witness.wtns", 10_000_000);
    }

    fn generateProofNode(self: *CircomVerifier, witness: []const u8) !CircomProof {
        try std.fs.cwd().writeFile("/tmp/witness.wtns", witness);

